17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.security.access.AccessDeniedException;
34	import org.springframework.validation.BindingResult;
35	import org.springframework.validation.FieldError;
36	import org.springframework.web.bind.MethodArgumentNotValidException;
37	import org.springframework.web.bind.annotation.ControllerAdvice;
38	import org.springframework.web.bind.annotation.ExceptionHandler;
39	import org.springframework.web.bind.annotation.ResponseBody;
40	
41	/**
42	 * Global Exception handler for REST controllers.
43	 * <p>
44	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
45	 *
46	 * @author Vitaliy Fedoriv
47	 * @author Alexander Dudkin
48	 */
49	@ControllerAdvice
50	public class ExceptionControllerAdvice {
51	
52	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
53	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
54	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
55	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
56	
57	    /**
58	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
59	     * class.
60	     *
61	     * @param e     Object referring to the thrown exception.
62	     * @param status HTTP response status.
63	     * @param url URL request.
64	     */
65	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
66	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
67	        problemDetail.setType(URI.create(url.toString()));
68	        problemDetail.setTitle(e.getClass().getSimpleName());
69	        problemDetail.setDetail(detail);
70	        problemDetail.setProperty("timestamp", Instant.now());
71	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
72	        return problemDetail;
73	    }
74	
75	    /**
76	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
77	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
78	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
79	     * would catch it and report an authorization failure as a 500.
80	     *
81	     * @param e The {@link AccessDeniedException} to propagate
82	     * @throws AccessDeniedException always
83	     */
84	    @ExceptionHandler(AccessDeniedException.class)
85	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
86	        throw e;
87	    }
88	
89	    /**
90	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
91	     *
92	     * @param e The {@link Exception} to be handled
93	     * @param request {@link HttpServletRequest} object referring to the current request.
94	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
95	     */
96	    @ExceptionHandler(Exception.class)
97	    @ResponseBody
98	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
99	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
100	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
101	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
102	        return ResponseEntity.status(status).body(detail);
103	    }
104	
105	    /**
106	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
107	     * method returns a 404 Not Found status if an entity does not exist.
108	     *
109	     * @param e The {@link DataIntegrityViolationException} to be handled
110	     * @param request {@link HttpServletRequest} object referring to the current request.
111	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
112	     */
113	    @ExceptionHandler(DataIntegrityViolationException.class)
114	    @ResponseBody
115	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
116	        logger.warn("Data integrity violation at {} {}: {}",
117	            request.getMethod(),
118	            request.getRequestURI(),
119	            e.getMessage());
120	        logger.debug("Data integrity violation stacktrace", e);
121	        HttpStatus status = HttpStatus.NOT_FOUND;
122	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
123	        return ResponseEntity.status(status).body(detail);
124	    }
125	
126	    /**
127	     * Handles exception thrown by Bean Validation on controller methods parameters
128	     *
129	     * @param e The {@link MethodArgumentNotValidException} to be handled
130	     * @param request {@link HttpServletRequest} object referring to the current request.
131	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
132	     */
133	    @ExceptionHandler(MethodArgumentNotValidException.class)
134	    @ResponseBody
135	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
136	        HttpStatus status = HttpStatus.BAD_REQUEST;
137	        BindingErrorsResponse errors = new BindingErrorsResponse();
138	        BindingResult bindingResult = e.getBindingResult();
139	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
140	        if (bindingResult.hasErrors()) {
141	            errors.addAllErrors(bindingResult);
142	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
143	                .map(fieldError -> {
144	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
145	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
146	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
147	                        fieldError.getField(),
148	                        defaultMessage,
149	                        rejectedValue);
150	                    return new ValidationMessageDto(message)
151	                        .putAdditionalProperty("field", fieldError.getField())
152	                        .putAdditionalProperty("rejectedValue", rejectedValue)
153	                        .putAdditionalProperty("defaultMessage", defaultMessage);
154	                })
155	                .toList();
156	            logger.debug("Validation error at {} {}: {}",
157	                request.getMethod(),
158	                request.getRequestURI(),
159	                bindingResult.getFieldErrors());
160	            List<String> fieldNames = bindingResult.getFieldErrors().stream()
161	                .map(FieldError::getField)
162	                .distinct()
163	                .toList();
164	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
165	            detail.setProperty("errors", fieldNames);
166	            return ResponseEntity.status(status).body(detail);
167	        }
168	        return ResponseEntity.status(status).body(detail);
169	    }
170	
171	    /**
172	     * Handles {@link RequiredFieldsMissingException} raised when a request omits or blanks one or
173	     * more required fields. Returns a 400 Bad Request whose body carries an {@code errors} array
174	     * listing the name of each offending field.
175	     *
176	     * @param e The {@link RequiredFieldsMissingException} to be handled
177	     * @param request {@link HttpServletRequest} object referring to the current request.
178	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
179	     */
180	    @ExceptionHandler(RequiredFieldsMissingException.class)
181	    @ResponseBody
182	    public ResponseEntity<ProblemDetail> handleRequiredFieldsMissingException(RequiredFieldsMissingException e, HttpServletRequest request) {
183	        HttpStatus status = HttpStatus.BAD_REQUEST;
184	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
185	        detail.setProperty("errors", e.getErrors());
186	        return ResponseEntity.status(status).body(detail);
187	    }
188	
189	    /**
190	     * Handles {@link InvalidTelephoneException} raised on create when the supplied telephone does
191	     * not normalize to exactly 10 digits. Returns a 400 Bad Request whose body carries an
192	     * {@code errors} array naming the {@code telephone} field.
193	     *
194	     * @param e The {@link InvalidTelephoneException} to be handled
195	     * @param request {@link HttpServletRequest} object referring to the current request.
196	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
197	     */
198	    @ExceptionHandler(InvalidTelephoneException.class)
199	    @ResponseBody
200	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
201	        HttpStatus status = HttpStatus.BAD_REQUEST;
202	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
203	        detail.setProperty("errors", List.of("telephone"));
204	        return ResponseEntity.status(status).body(detail);
205	    }
206	
207	    /**
208	     * Handles {@link InvalidEmailException} raised on create when the supplied email is present but
209	     * is not a syntactically valid address. Returns a 400 Bad Request whose body carries an
210	     * {@code errors} array naming the {@code email} field.
211	     *
212	     * @param e The {@link InvalidEmailException} to be handled
213	     * @param request {@link HttpServletRequest} object referring to the current request.
214	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
215	     */
216	    @ExceptionHandler(InvalidEmailException.class)
217	    @ResponseBody
218	    public ResponseEntity<ProblemDetail> handleInvalidEmailException(InvalidEmailException e, HttpServletRequest request) {
219	        HttpStatus status = HttpStatus.BAD_REQUEST;
220	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
221	        detail.setProperty("errors", List.of("email"));
222	        return ResponseEntity.status(status).body(detail);
223	    }
224	
225	    /**
226	     * Handles {@link InvalidPostcodeException} raised on create when a supplied postcode is not four
227	     * digits or is out of range for the owner's city region. Returns a 400 Bad Request whose body
228	     * carries an {@code errors} array naming the {@code postcode} field.
229	     *
230	     * @param e The {@link InvalidPostcodeException} to be handled
231	     * @param request {@link HttpServletRequest} object referring to the current request.
232	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
233	     */
234	    @ExceptionHandler(InvalidPostcodeException.class)
235	    @ResponseBody
236	    public ResponseEntity<ProblemDetail> handleInvalidPostcodeException(InvalidPostcodeException e, HttpServletRequest request) {
237	        HttpStatus status = HttpStatus.BAD_REQUEST;
238	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
239	        detail.setProperty("errors", List.of("postcode"));
240	        return ResponseEntity.status(status).body(detail);
241	    }
242	
243	    /**
244	     * Handles {@link DuplicateTelephoneException} raised on create when the supplied telephone,
245	     * after normalization, is already used by another owner. Returns a 409 Conflict whose body
246	     * carries an {@code errors} array naming the {@code telephone} field.
247	     *
248	     * @param e The {@link DuplicateTelephoneException} to be handled
249	     * @param request {@link HttpServletRequest} object referring to the current request.
250	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
251	     */
252	    @ExceptionHandler(DuplicateTelephoneException.class)
253	    @ResponseBody
254	    public ResponseEntity<ProblemDetail> handleDuplicateTelephoneException(DuplicateTelephoneException e, HttpServletRequest request) {
255	        HttpStatus status = HttpStatus.CONFLICT;
256	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
257	        detail.setProperty("errors", List.of("telephone"));
258	        return ResponseEntity.status(status).body(detail);
259	    }
260	
261	    /**
262	     * Handles {@link DuplicateHouseholdException} raised on create when another owner already has the
263	     * same last name and address (compared case-insensitively with collapsed whitespace) and the
264	     * request did not opt in via {@code sharesHousehold}. Returns a 409 Conflict whose body carries an
265	     * {@code errors} array naming the {@code lastName} and {@code address} fields.
266	     *
267	     * @param e The {@link DuplicateHouseholdException} to be handled
268	     * @param request {@link HttpServletRequest} object referring to the current request.
269	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
270	     */
271	    @ExceptionHandler(DuplicateHouseholdException.class)
272	    @ResponseBody
273	    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(DuplicateHouseholdException e, HttpServletRequest request) {
274	        HttpStatus status = HttpStatus.CONFLICT;
275	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
276	        detail.setProperty("errors", List.of("lastName", "address"));
277	        return ResponseEntity.status(status).body(detail);
278	    }
279	
280	    /**
281	     * Handles {@link DuplicateEmailException} raised on create when the supplied email, after
282	     * lower-casing, is already used by another owner. Returns a 409 Conflict whose body carries an
283	     * {@code errors} array naming the {@code email} field.
284	     *
285	     * @param e The {@link DuplicateEmailException} to be handled
286	     * @param request {@link HttpServletRequest} object referring to the current request.
287	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
288	     */
289	    @ExceptionHandler(DuplicateEmailException.class)
290	    @ResponseBody
291	    public ResponseEntity<ProblemDetail> handleDuplicateEmailException(DuplicateEmailException e, HttpServletRequest request) {
292	        HttpStatus status = HttpStatus.CONFLICT;
293	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
294	        detail.setProperty("errors", List.of("email"));
295	        return ResponseEntity.status(status).body(detail);
296	    }
297	
298	    /**
299	     * Handles {@link DuplicateIdentityException} raised on create when a new owner's whole derived
300	     * {@code identityKey} equals that of an existing owner. Returns a 409 Conflict whose body carries
301	     * an {@code errors} array naming the {@code identityKey} field.
302	     *
303	     * @param e The {@link DuplicateIdentityException} to be handled
304	     * @param request {@link HttpServletRequest} object referring to the current request.
305	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
306	     */
307	    @ExceptionHandler(DuplicateIdentityException.class)
308	    @ResponseBody
309	    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
310	        HttpStatus status = HttpStatus.CONFLICT;
311	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
312	        detail.setProperty("errors", List.of("identityKey"));
313	        return ResponseEntity.status(status).body(detail);
314	    }
315	
316	    /**
317	     * Handles {@link CityAtCapacityException} raised on create when the owner's city already contains
318	     * 50 or more owners (compared case-insensitively with surrounding whitespace trimmed). Returns a
319	     * 409 Conflict whose body carries an {@code errors} array naming the {@code city} field.
320	     *
321	     * @param e The {@link CityAtCapacityException} to be handled
322	     * @param request {@link HttpServletRequest} object referring to the current request.
323	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
324	     */
325	    @ExceptionHandler(CityAtCapacityException.class)
326	    @ResponseBody
327	    public ResponseEntity<ProblemDetail> handleCityAtCapacityException(CityAtCapacityException e, HttpServletRequest request) {
328	        HttpStatus status = HttpStatus.CONFLICT;
329	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
330	        detail.setProperty("errors", List.of("city"));
331	        return ResponseEntity.status(status).body(detail);
332	    }
333	
334	    /**
335	     * Handles {@link DailyOwnerLimitExceededException} raised on create when 100 or more owners have
336	     * already been created today (counted by {@code registrationDate}). Returns a 429 Too Many
337	     * Requests whose body carries an {@code errors} array naming the {@code registrationDate} field.
338	     *
339	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
340	     * @param request {@link HttpServletRequest} object referring to the current request.
341	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
342	     */
343	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
344	    @ResponseBody
345	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
346	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
347	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
348	        detail.setProperty("errors", List.of("registrationDate"));
349	        return ResponseEntity.status(status).body(detail);
350	    }
351	
352	    /**
353	     * Handles {@link FutureRegistrationDateException} raised on create when the supplied
354	     * {@code registrationDate} is later than the server date. Returns a 400 Bad Request whose body
355	     * carries an {@code errors} array naming the {@code registrationDate} field.
356	     *
357	     * @param e The {@link FutureRegistrationDateException} to be handled
358	     * @param request {@link HttpServletRequest} object referring to the current request.
359	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
360	     */
361	    @ExceptionHandler(FutureRegistrationDateException.class)
362	    @ResponseBody
363	    public ResponseEntity<ProblemDetail> handleFutureRegistrationDateException(FutureRegistrationDateException e, HttpServletRequest request) {
364	        HttpStatus status = HttpStatus.BAD_REQUEST;
365	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
366	        detail.setProperty("errors", List.of("registrationDate"));
367	        return ResponseEntity.status(status).body(detail);
368	    }
369	
370	}
